from hdr import *
r.append(R(7393112,"सेलेरिएक चिप्स के साथ रोस्ट चिकन",
"अपने अगले रोस्ट चिकन व्यंजन में सेलेरिएक चिप्स के साथ नयापन लाएँ! यह रेसिपी स्लिमिंग वर्ल्ड के साथ साझेदारी में चुनी गई है।",
"6","404 ग्राम",
["1.5 किलो पूरा चिकन","1 नींबू","1 किलो बड़ा (या 2 छोटे) सेलेरिएक, छिला हुआ और फ्राइज़ की तरह कटा हुआ","कम कैलोरी वाला कुकिंग स्प्रे",["ड्रेसिंग के लिए","छोटा पैकेट ताज़ा टैरागन, बारीक कटा हुआ"],["ड्रेसिंग के लिए","4-6 शैलट (छोटे प्याज़), बारीक कटे हुए"],["ड्रेसिंग के लिए","2 छोटे चम्मच डिजॉन सरसों (समतल भरे हुए)"],["ड्रेसिंग के लिए","2 नींबू का रस, साथ में 1 बिना मोम वाले नींबू का छिलका"],["हरी पत्तियों के लिए","1 बड़ी लहसुन की फांक, पतली कटी हुई"],["हरी पत्तियों के लिए","250 ग्राम कावोलो नेरो, बारीक कतरी हुई"]],
["अपने ओवन को 200°C/फैन 180°C/गैस 6 पर पहले से गरम करें।","चिकन को नॉन-स्टिक बेकिंग ट्रे पर रखें और नींबू को उसके पेट में डालें। 1 घंटे तक भूनें, या जब तक अंदर तक पक न जाए (चिकन के सबसे मोटे हिस्से में सींक डालने पर रस साफ़ निकलना चाहिए)।","इसी बीच, सेलेरिएक चिप्स को एक बड़ी नॉन-स्टिक बेकिंग ट्रे पर एक ही परत में फैलाएँ। कम कैलोरी वाले कुकिंग स्प्रे के दो-तीन पंप छिड़कें और जब चिकन के पकने में 30 मिनट बचे हों, तब उन्हें चिकन के नीचे वाले ओवन के खाने में रखें।","चिकन को ओवन से निकालें, फ़ॉइल से ढक दें और आराम करने दें। चिप्स को पलटें और 15-20 मिनट और पकाएँ, या जब तक सुनहरे और नरम न हो जाएँ। इसी बीच, ड्रेसिंग की सामग्री को 1-2 बड़े चम्मच पानी के साथ मिलाएँ और काली मिर्च डालें। आधा एक तरफ़ रख दें, फिर ढककर अगले दिन के लिए ठंडा रखें।","एक नॉन-स्टिक फ्राइंग पैन पर कम कैलोरी वाले कुकिंग स्प्रे के दो-तीन पंप छिड़कें और मध्यम-तेज़ आँच पर रखें। लहसुन को सुनहरा होने तक भूनें, फिर कावोलो नेरो डालें, काली मिर्च डालें, थोड़ा पानी छिड़कें और 5 मिनट तक तेज़ आँच पर चलाते हुए भूनें, जब तक नरम न हो जाए।","चिकन की त्वचा हटा दें और दिखाई देने वाली कोई भी चर्बी निकाल दें, फिर स्लाइस करें। चिकन, चिप्स और लहसुन वाली हरी पत्तियों को प्लेटों में बाँटें, ऊपर से ड्रेसिंग डालें और थोड़ी ताज़ी पिसी काली मिर्च डालें।"],
["यदि इसकी 2 सर्विंग बच जाएँ, तो ठंडा करें, ढकें और अगले दिन तक फ्रिज में रखें। चिकन और दलिया (बुलगुर गेहूँ) का सलाद बनाने के लिए, 70 ग्राम सूखा बुलगुर गेहूँ पैकेट पर दिए निर्देशों के अनुसार पकाएँ। चिकन को रेशे-रेशे करें और चिप्स तथा हरी पत्तियों को काट लें। सब कुछ बची हुई ड्रेसिंग और 1/2 छोटे पैकेट कटे हुए ताज़े अजमोदा (पार्सले) के साथ मिलाएँ। परोसने के लिए 2 प्लेटों में बाँटें।",fv(2)]))
r.append(R(7393124,"भुने बटरनट स्क्वैश के साथ गैलिशियन स्टू",
"स्पेनिश अंदाज़ से प्रेरित व्यंजन, जो पौष्टिकता से भरपूर है।",
"4","581 ग्राम",
["1 मध्यम बटरनट स्क्वैश (लगभग 900 ग्राम)","1 बड़ा चम्मच ऑलिव ऑयल","1 हरी शिमला मिर्च, बीज निकालकर पट्टियों में कटी हुई","1 पीली शिमला मिर्च, बीज निकालकर पट्टियों में कटी हुई","1 लाल शिमला मिर्च, बीज निकालकर पट्टियों में कटी हुई","1 बड़ा प्याज़, आधा करके फिर पतला कटा हुआ","2 ढेर वाले छोटे चम्मच हल्की ('डुल्से') स्मोक्ड पपरिका","2–3 फांक लहसुन, कटी हुई","1 गोल भरा छोटा चम्मच सूखा थाइम","1 बैंगन, बड़े टुकड़ों में कटा हुआ","1 x 400 ग्राम का डिब्बा टमाटर, साथ में 1 डिब्बा पानी","400 ग्राम का डिब्बा पुय दालें (लेंटिल)","2 बड़े चम्मच ताज़ा कटा अजमोदा (पार्सले)"],
["ओवन को 190°C/गैस 5 पर पहले से गरम करें। बटरनट स्क्वैश को लंबाई में चार टुकड़ों में काटें। बीज निकालें और हर टुकड़े पर 1/2 बड़ा चम्मच ऑलिव ऑयल लगाएँ, फिर ओवन-प्रूफ़ डिश या ट्रे में रखकर ओवन में 30 मिनट बेक करें, जब तक वे नरम न हो जाएँ और भूरे होने न लगें।","इसी बीच, एक बड़े पैन में मध्यम आँच पर बचा हुआ तेल डालें, शिमला मिर्च और प्याज़ डालें और 5 मिनट तक बार-बार चलाएँ। इसके बाद पपरिका, लहसुन, थाइम, बैंगन, टमाटर और पानी डालें। उबाल आने दें, चलाएँ और ढक दें, फिर आँच धीमी करें और 15 मिनट तक धीमी आँच पर पकाएँ।","दालें डालें, ढक्कन वापस लगाएँ और 3-4 मिनट और धीमी आँच पर पकाएँ।","पकने के बाद, बटरनट स्क्वैश को ओवन से निकालें। दाल के मिश्रण का चौथाई हिस्सा स्क्वैश पर चम्मच से डालें, ऊपर से ढेर सारा कटा अजमोदा छिड़कें और चार प्लेटों में बाँट दें। बचा हुआ दाल का मिश्रण अलग कटोरे में रखें और स्क्वैश के साथ परोसें।"],
["यह सब्ज़ी स्टू बटरनट स्क्वैश की जगह बेक किए हुए शकरकंद या भुने कद्दू पर डालकर भी बहुत अच्छा लगता है। आप इसे मैरो (एक प्रकार की लौकी) के बड़े छल्लों में भरकर भून भी सकते हैं। या ऊपर से फ़ाइलो पेस्ट्री लगाकर सब्ज़ी की पाई बना सकते हैं।","स्मोक्ड पपरिका स्पेनिश व्यंजनों में इस्तेमाल करने के लिए एक अच्छा मसाला है। इसमें बिना चर्बी के चोरिज़ो का स्वाद होता है। आप 'डुल्से' नाम का हल्का संस्करण या 'पिकांते' नाम का ज़्यादा तीखा संस्करण खरीद सकते हैं। यह सूप, स्टू, भुने माँस या सब्ज़ियों में एक सुंदर, धुएँदार, गरमाहट भरा गाढ़ापन जोड़ता है।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। स्टू और स्क्वैश को अलग-अलग फ्रीज़ करें। फ्रिज या माइक्रोवेव में डीफ़्रॉस्ट करें और अंदर तक गरम होने तक दोबारा गरम करें।",fv(6)]))
r.append(R(7393623,"मिंस पाई",
"क्रिसमस की एक पुरानी पसंदीदा मिठाई का ज़्यादा सेहतमंद रूप। पेस्ट्री में साबुत गेहूँ का आटा इस्तेमाल होता है जिसमें फाइबर ज़्यादा होता है। बिना ऊपरी परत वाली (\"टॉपलेस\") क्रस्ट वसा और कैलोरी कम करती है, फिर भी इसमें क्रिसमस के सारे स्वाद मौजूद हैं।",
"12","58 ग्राम",
[["पेस्ट्री के लिए","150 ग्राम साबुत गेहूँ का आटा"],["पेस्ट्री के लिए","75 मिलीलीटर रेपसीड तेल"],["पेस्ट्री के लिए","50 मिलीलीटर ठंडा पानी"],["भरावन के लिए","150 ग्राम शाकाहारी मिंसमीट"],["भरावन के लिए","75 ग्राम सेब, कद्दूकस किया हुआ, बिना छिला"],["भरावन के लिए","50 ग्राम गाजर, कद्दूकस की हुई"],["भरावन के लिए","1 बड़ा चम्मच सूरजमुखी के बीज"],["भरावन के लिए","1 ढेर वाला छोटा चम्मच मिक्स्ड स्पाइस"],["टॉपिंग के लिए","आधा सेब, बारीक कटा हुआ"],["टॉपिंग के लिए","आधा नाशपाती, बारीक कटी हुई"],["टॉपिंग के लिए","थोड़ा-सा नींबू का रस"],["टॉपिंग के लिए","1 ताज़ा अंजीर, छोटी फाँकों में कटा हुआ"],["टॉपिंग के लिए","3 अखरोट के आधे टुकड़े"],["टॉपिंग के लिए","3 ग्लेसे चेरी, आधी कटी हुई"],["टॉपिंग के लिए","2 छोटे चम्मच भुने हुए, कतरे हुए बादाम"],["टॉपिंग के लिए","कद्दूकस किया हुआ संतरे का छिलका"]],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। सारी सामग्री को एक साथ मिलाकर पेस्ट्री बनाएँ, फिर कुछ बार गूँधें। गोला बना लें, क्लिंग फ़िल्म से ढकें और 20 मिनट के लिए फ्रिज में रखें।","इसी बीच, मिंसमीट को कद्दूकस किए हुए सेब, गाजर, सूरजमुखी के बीज और मिक्स्ड स्पाइस के साथ मिलाएँ।","पेस्ट्री को बेल लें, गोल टुकड़ों में काटें और 12 खानों वाली छिछली बन टिन में बिछा दें।","मिंसमीट का मिश्रण पेस्ट्री केसों में इतना भरें कि वे तीन-चौथाई भर जाएँ, फिर ओवन में 15-20 मिनट बेक करें। पकने के बाद, ओवन से निकालें और जाली पर ठंडा होने दें।","टॉपिंग तैयार करें (सामग्री सूची देखें), सेब और नाशपाती पर नींबू का रस निचोड़ें ताकि वे भूरे न पड़ें।","परोसने से ठीक पहले, पाई को अलग-अलग टॉपिंग सामग्री से सजाएँ: ताज़े अंजीर की फाँक और एक अखरोट: 1 छोटा चम्मच सेब या नाशपाती, साथ में एक चेरी: कुछ भुने कतरे बादाम और संतरे का छिलका, या अपनी पसंद का कोई भी मेल – अपनी कल्पना का इस्तेमाल करें!"],
["नींबू-जैसी ताज़गी के लिए, मिंसमीट में एक संतरे या नींबू का कद्दूकस किया छिलका डालकर देखें।","आप मिक्स्ड स्पाइस की जगह पिसी दालचीनी, जायफल या अदरक भी डाल सकते हैं।","फ्रीज़ करने के निर्देश: परोसने के लिए 2 घंटे डीफ़्रॉस्ट करें, या माइक्रोवेव या मध्यम गरम ओवन में डीफ़्रॉस्ट करें।",fv(0)]))
r.append(R(7396460,"झटपट फ्रूट ब्रेड",
"दालचीनी, किशमिश और केले वाली नरम बनावट की सोडा ब्रेड, जो मिनटों में तैयार हो जाती है। इसे ऐसे ही खाया जा सकता है या हल्का टोस्ट करके।",
"10","52 ग्राम",
["1 छोटा चम्मच सूरजमुखी तेल","75 ग्राम किशमिश","100 मिलीलीटर उबलता पानी","1 ढेर वाला छोटा चम्मच पिसी दालचीनी","1 केला (छिलका उतारकर लगभग 100 ग्राम)","4 बड़े चम्मच कम वसा वाला सादा दही","175 ग्राम साबुत गेहूँ का आटा","1 छोटा चम्मच बेकिंग सोडा"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। सूरजमुखी तेल से 1 पाउंड वाली लोफ़ टिन (लगभग 19 सेमी x 10 सेमी) को हल्का चिकना करें।","किशमिश को दालचीनी और 100 मिलीलीटर उबलते पानी के साथ एक कटोरे में रखें। एक तरफ़ रख दें।","दूसरे कटोरे में केले को मैश करें और दही के साथ मिलाएँ।","एक बड़े कटोरे में आटा और बेकिंग सोडा मिलाएँ।","केले और दही का मिश्रण आटे के मिश्रण में डालें। किशमिश और पानी डालें और अच्छी तरह मिलाएँ। मिश्रण को लोफ़ टिन में डालें।","25 मिनट तक बेक करें, जब तक ब्रेड ठोस और सुनहरी न हो जाए। जब बीच में चाकू डालने पर साफ़ निकले, तो ब्रेड पक गई है।"],
["गीली सामग्री को सूखी सामग्री में मिलाते ही बेकिंग सोडा सक्रिय हो जाता है, इसलिए अधिकतम हल्केपन के लिए इसे जल्दी से ओवन में रख दें।","आप किशमिश की जगह कोई भी सूखा फल इस्तेमाल कर सकते हैं, जैसे कटी हुई खुबानी, सुल्ताना, आलूबुखारा (प्रून) या मिले-जुले सूखे फल।","एक छोटा चम्मच मिक्स्ड स्पाइस या एक चुटकी पिसी लौंग डालकर देखें।","आप इस ब्रेड को साबुत या स्लाइस करके तीन महीने तक फ्रीज़ कर सकते हैं। बस फ़ॉइल में लपेटें, फ्रीज़र बैग में रखें और लेबल लगा दें। इस फलों वाली ब्रेड को फ्रीज़र से सीधे टोस्ट किया जा सकता है।"]))
r.append(R(7398904,"टमाटर सॉस और तोरी के साथ बैंगन के 'मीटबॉल'",
"इस इतालवी क्लासिक का सेहतमंद वीगन संस्करण, जिसमें अतिरिक्त स्वाद के लिए तोरी (कूजेट) है।",
"4","464 ग्राम",
["250 ग्राम छिला हुआ शकरकंद, कटा हुआ","600 ग्राम बैंगन","1 लाल प्याज़, बारीक कटा हुआ","2 लहसुन की फांकें, कुचली हुई","1/2 नींबू का बारीक कद्दूकस किया हुआ छिलका","1/2 लाल मिर्च, बीज निकालकर कटी हुई","1 छोटा चम्मच कटा हुआ ताज़ा रोज़मेरी","3 बड़े चम्मच तिल","1 सफ़ेद प्याज़, मोटा कटा हुआ","1 छोटा चम्मच ऑलिव ऑयल, 400 ग्राम का डिब्बा कटे हुए टमाटर","1 बड़ा चम्मच बाल्सामिक सिरका","1 छोटा चम्मच चीनी","4 बड़ी तोरी (कूजेट)","1 कैल स्प्रे सूरजमुखी तेल"],
["शकरकंद को 8-10 मिनट तक उबालें जब तक नरम न हो जाए, छानें, मैश करें और एक तरफ़ रख दें।","बैंगन को 1 सेमी के टुकड़ों में काटें। नॉन-स्टिक फ्राइंग पैन पर ऑलिव ऑयल स्प्रे करें और बैंगन, प्याज़ और लहसुन डालें। ढककर धीमी/मध्यम आँच पर 15 मिनट पकाएँ, बीच-बीच में चलाते रहें। ढक्कन हटाएँ और 5 मिनट और पकाएँ।","इसे फूड प्रोसेसर में डालें और 5 सेकंड तक पल्स करें ताकि बारीक कट जाए पर पेस्ट न बने; थोड़ी बनावट होने पर मीटबॉल ज़्यादा अच्छे लगते हैं। इसे कटोरे में निकालें, मैश किया आलू, छिलका, मिर्च और रोज़मेरी डालें और अच्छी तरह मिलाएँ। बाँटकर 12 गोले बना लें। एक प्लेट में तिल बिखेरें और हर गोले को तिल में लपेटें। सख़्त होने के लिए 10 मिनट फ्रिज में रखें।","ओवन को 180°C/गैस 4 पर पहले से गरम करें। गोलों को ओवन-प्रूफ़ डिश में रखें, हल्का तेल स्प्रे करें और 20-25 मिनट तक कुरकुरे होने तक पकाएँ।","इसी बीच सॉस बनाएँ। एक छोटे फ्राइंग पैन को गरम करें और धीमी आँच पर प्याज़ को तेल में नरम होने तक पकाएँ। टमाटर, सिरका और चीनी डालें, ढककर 10 मिनट तक धीमी आँच पर पकाएँ, बीच-बीच में चलाते रहें।","इसी बीच, हर तोरी को लंबाई में 5 मिमी के स्लाइस में काटें। दोनों तरफ़ थोड़ा-सा 1 कैल सूरजमुखी तेल स्प्रे करें और ग्रिल पैन पर हर तरफ़ 4-5 मिनट पकाएँ, जब तक वे जल न जाएँ (चारिंग हो जाए) और नरम न हो जाएँ। पतली पट्टियों में काटें, परोसने की प्लेटों में बाँटें, ऊपर से सॉस और बैंगन के गोले रखकर परोसें।"],
[fv(4)]))
r.append(R(7400058,"रोज़मेरी वाले बेक्ड प्याज़",
"प्याज़ का आसान, झटपट और बिना गंदगी वाला रूप - एक स्वादिष्ट साइड डिश।",
"4","210 ग्राम",
["4 बड़े प्याज़","1 बड़ा चम्मच बाल्सामिक सिरका","4 छोटे चम्मच ऑलिव ऑयल","4 फांक लहसुन","रोज़मेरी की टहनियाँ","अच्छी तरह पिसी हुई काली मिर्च"],
["ओवन को 180°C/गैस 5 पर पहले से गरम करें। प्याज़ की ऊपरी कागज़ जैसी परत हटाएँ, छिलके को बरकरार रखें, फिर उनके ऊपर और नीचे के सिरे काट दें।","हर प्याज़ के ऊपर क्रॉस का निशान काटें, चार हिस्सों में काटने के लिए नीचे की ओर चीरें, लेकिन केवल तीन-चौथाई तक ही, ताकि प्याज़ साबुत बने रहें।","हर प्याज़ को फ़ॉइल के एक चौकोर टुकड़े पर रखें और ऊपर से खुला ढीला-सा पैकेट बनाएँ। 4 फांक लहसुन को 5-5 स्लाइस में काटें, फिर हर क्रॉस चीरे में एक स्लाइस और बीच में एक स्लाइस डालें, नीचे गुठली (कोर) तक दबाएँ।","रोज़मेरी की टहनियों के साथ भी यही करें, हर प्याज़ के लिए एक टहनी इस्तेमाल करें, टहनियों को छोटे टुकड़ों में तोड़ लें।","हर पैकेट में बाल्सामिक सिरका, ऑलिव ऑयल और थोड़ी काली मिर्च डालें। फिर फ़ॉइल के कोनों को ऊपर उठाएँ और ऊपर से मरोड़कर बंद कर दें। 45 मिनट तक बेक करें।"],
["अंदर बंद सुगंध का आनंद लेने के लिए फ़ॉइल का पैकेट मेज़ पर खोलें।","छोटे प्याज़ इस्तेमाल करें, लेकिन पकाने का समय 10 मिनट कम कर दें।","रोज़मेरी के विकल्प के रूप में थाइम या सेज की ताज़ी टहनियाँ इस्तेमाल करें।",fv(2)]))
r.append(R(7403442,"पुदीना, मटर और क्रेम फ्रेश सूप",
"एक ताज़गी भरा सूप जो जल्दी और आसानी से बन जाता है।",
"2","499 ग्राम",
["400 ग्राम फ्रोज़न पेटी पुआ (छोटे मटर)","10 सेमी खीरे का टुकड़ा, मोटा कटा हुआ","10 बड़ी ताज़ी पुदीने की पत्तियाँ","10 बड़ी ताज़ी तुलसी की पत्तियाँ","बड़ी मुट्ठी भर वॉटरक्रेस","300 मिलीलीटर सब्ज़ी का जूस","200 मिलीलीटर पानी","4 बड़े चम्मच कम वसा वाला क्रेम फ्रेश"],
["एक बड़े पैन में पानी उबालें, मटर, खीरा, पुदीना, तुलसी और वॉटरक्रेस डालें और 5 मिनट तक धीमी आँच पर पकाएँ। छान लें। 2 बड़े चम्मच मटर अलग रख दें, फिर बाकी मिश्रण को पैन में वापस डालें। जूस और पानी डालें, और लगभग उबाल आने तक गरम करें।","आँच से उतारें और क्रेम फ्रेश मिलाएँ। चिकना होने तक ब्लेंड करें।","दो कटोरों में बाँटें, बचे हुए मटर ऊपर से बिखेरें, थोड़ा अतिरिक्त क्रेम फ्रेश और ताज़ी पिसी काली मिर्च ऊपर से डालें।"],
[fv(3)]))
r.append(R(7403886,"पिस्तू के साथ चिकन, बोरलोटी बीन्स और सब्ज़ियों का सूप",
"इस स्वादिष्ट सेहतमंद सूप से मौसमी हरी सब्ज़ियों का भरपूर लाभ उठाएँ, जिसमें ताज़ा जड़ी-बूटियों वाला पिस्तू (पेस्टो का फ्रांसीसी रूप) इस्तेमाल होता है।",
"4","278 ग्राम",
["एक छोटी मुट्ठी ताज़ा चपटी पत्ती वाला अजमोदा (पार्सले), मोटा कटा हुआ","एक छोटी मुट्ठी ताज़ी पुदीने की पत्तियाँ, मोटी कटी हुई","1/2 नींबू का कद्दूकस किया हुआ छिलका, 2 लहसुन की फांकें, कुचली हुई","कैलोरी-नियंत्रित कुकिंग स्प्रे","1 छोटी लीक, पतली कटी हुई","2 x 165 ग्राम बिना त्वचा के चिकन ब्रेस्ट फ़िलेट","1.5 लीटर चिकन स्टॉक, 1 कम नमक वाले स्टॉक क्यूब से बना हुआ","100 ग्राम ब्रोकली, फूलों के रूप में कटी हुई","200 ग्राम शतावरी (एस्पेरेगस), छँटी और कटी हुई","120 ग्राम फ्रोज़न मटर","400 ग्राम का डिब्बा बोरलोटी बीन्स, छानी हुई","100 ग्राम शुगर स्नैप मटर, कटी हुई"],
["पिस्तू बनाएँ। अजमोदा, पुदीना, नींबू का छिलका और आधा लहसुन फूड प्रोसेसर में 1 छोटा चम्मच पानी के साथ डालें और चिकना होने तक पीस लें।","एक बड़े सॉसपैन पर कुकिंग स्प्रे की हल्की फुहार करें, फिर मध्यम आँच पर रखें। लीक और बचा हुआ लहसुन डालें, और चलाते हुए 5 मिनट पकाएँ या जब तक नरम न हो जाए।","साबुत चिकन ब्रेस्ट और स्टॉक को लीक वाले पैन में डालें, और ढककर 15 मिनट तक धीमी आँच पर पकाएँ, या जब तक चिकन अंदर तक पक न जाए। छेदवाले चम्मच से चिकन को बोर्ड पर निकालें। 5 मिनट आराम करने दें, फिर पतले स्लाइस काटें।","ब्रोकली, शतावरी, मटर और बोरलोटी बीन्स सूप में डालें और उबाल आने दें। आँच कम करें और बिना ढके 3 मिनट धीमी आँच पर पकाएँ। शुगर स्नैप मटर और कटा हुआ चिकन डालें, फिर बिना ढके 2 मिनट पकाएँ, या जब तक सब्ज़ियाँ बस नरम न हो जाएँ। सूप के ऊपर पिस्तू डालकर परोसें।"],[]))
r.append(R(7404450,"सावरडो स्टार्टर के साथ मसालेदार छोले का सूप",
"हमने यह मसालेदार छोले का सूप सावरडो स्टार्टर के साथ बॉक्सिंग डे पर अपने टर्की स्टॉक से बनाया था। इसे अच्छे माँस वाले स्टॉक से बहुत फ़ायदा मिलता है।",
"8","50 ग्राम",
["2 प्याज़, कटे हुए","ऑलिव ऑयल","200 ग्राम छोले, रात भर भिगोकर पकाए हुए","150 ग्राम दालें (लेंटिल), धुली हुई","500 ग्राम टमाटर, कटे हुए","4 सेलेरी के डंठल, कटे हुए","1 बड़ा चम्मच टमाटर प्यूरी","1 छोटा चम्मच अदरक","2 दालचीनी की डंडियाँ","1 छोटा चम्मच हल्दी","1 लीटर माँस का स्टॉक","1 कप सावरडो स्टार्टर","भरपूर मात्रा में काली मिर्च","मुट्ठी भर धनिया और अजमोदा (पार्सले), मोटा कटा हुआ","1 नींबू का रस"],
["थोड़ा-सा तेल गरम करें और प्याज़ डालें। नरम होने तक पकाएँ","छोले, दालें, टमाटर और सेलेरी डालें","टमाटर प्यूरी और मसाले डालें, 5 मिनट पकाएँ","इसके बाद स्टॉक डालें","जब स्टॉक अंदर तक गरम हो जाए तो उसके 2 कप सावरडो स्टार्टर में डालें","जब अच्छी तरह मिल जाए तो धीरे-धीरे वापस सूप में डाल दें","जब सब्ज़ियाँ और दालें नरम हो जाएँ तो सूप को ब्लेंड करें, मनचाहा गाढ़ापन पाने के लिए पानी मिलाएँ","कटी हुई जड़ी-बूटियाँ डालें और स्वादानुसार नमक-मसाला समायोजित करें।"],[]))
r.append(R(7406405,"गरम विदेशी फलों का सलाद",
"एक सुगंधित और ताज़गी भरी मिठाई।",
"4","208 ग्राम",
["2 इलायची की फलियाँ, कुचली हुई","1 बड़ा चम्मच ताज़ा पुदीना, कटा हुआ","जार में संरक्षित अदरक (स्टेम जिंजर) का 1 टुकड़ा, बारीक कटा हुआ, साथ में उसकी 2 बड़े चम्मच चाशनी","1 अनानास, तैयार करके टुकड़ों में कटा हुआ (तैयार वज़न 500 ग्राम)","1 पपीता, छिला, बीज निकालकर टुकड़ों में कटा हुआ","1 कीवी फल, कटा हुआ"],
["इलायची की फलियाँ, पुदीना, अदरक की चाशनी और 2 बड़े चम्मच पानी को एक पैन में डालें। उबाल आने दें।","आँच से उतारें और 15 मिनट ठंडा होने दें।","तैयार फलों के ऊपर डालें, 10 मिनट रखा रहने दें और परोसें।"],
["थोड़े आधी वसा वाले क्रेम फ्रेश या डेयरी-मुक्त विकल्प के साथ स्वादिष्ट लगता है।","यदि आपके पास इलायची की फलियाँ नहीं हैं, तो आप एक अच्छी चुटकी दालचीनी या मिक्स्ड स्पाइस इस्तेमाल कर सकते हैं।",fv(2)]))
r.append(R(7414318,"सैल्मन, लाल प्याज़ और मीठी शिमला मिर्च के रैप",
"लाल सैल्मन को बारीक कटे लाल प्याज़ और शिमला मिर्च के साथ नींबू वाले दही में मिलाकर, सलाद से भरा गया। दोपहर के पैक्ड लंच या पिकनिक के लिए बढ़िया।",
"2","363 ग्राम",
["200 ग्राम का डिब्बा लाल सैल्मन","आधा लाल प्याज़, बारीक कटा हुआ","1 लाल शिमला मिर्च, बारीक कटी हुई","50 ग्राम खीरा, बारीक टुकड़ों में कटा हुआ","50 ग्राम कम वसा वाला दही","आधे नींबू का रस","अच्छी तरह पिसी काली मिर्च","2 साबुत गेहूँ के टॉर्टिला, प्रत्येक 70 ग्राम","50 ग्राम सलाद की पत्तियाँ"],
["सैल्मन को छान लें और त्वचा हटा दें, लेकिन काँटे (हड्डियाँ) रहने दें क्योंकि वे कैल्शियम से भरपूर होते हैं। इसे कटोरे में डालें और काँटे से मोटा-मोटा मसल लें।","प्याज़, शिमला मिर्च, खीरा, दही, नींबू का रस और काली मिर्च को सैल्मन में डालें और अच्छी तरह मिलाएँ।","टॉर्टिला को सूखे फ्राइंग पैन या ग्रिल पैन में 1-2 मिनट गरम करें। साफ़ कार्य-सतह पर रखें, सलाद और सैल्मन को दोनों टॉर्टिला में बाँटें, मिश्रण को बीच में रखें और किनारों के चारों ओर 3-4 सेमी जगह छोड़ें।","किनारों को अंदर दबाते हुए लपेटें, फिर परोसने के लिए तिरछा आधा काट लें।"],
["पैक्ड लंच या पिकनिक के लिए, भरे हुए टॉर्टिला को ग्रीसप्रूफ़ पेपर या फ़ॉइल में कसकर लपेटें, सिरों को मरोड़कर सुरक्षित करें। खाते समय बस एक सिरा खोलें और खाते-खाते कागज़ को उतारते जाएँ, उसे सर्पिल आकार में फाड़ते हुए नीचे की ओर बढ़ें।","सैल्मन की जगह डिब्बाबंद मैकरल, सार्डिन या टूना इस्तेमाल करके देखें और थोड़े मिर्च पाउडर से मसालेदार बनाएँ, या ताज़ा धनिया या सोआ (डिल) जैसी जड़ी-बूटियाँ डालें।",fv(1)]))
r.append(R(7415142,"तोरी (कूजेट) लोफ़",
"अमेरिका में ज़ुकिनी ब्रेड के नाम से जानी जाने वाली, यह एक लोकप्रिय पसंदीदा और दोपहर की चाय के लिए एकदम सही ब्रेड है। इसमें कद्दूकस की हुई तोरी बड़ी मात्रा में होती है और यह केले की ब्रेड जैसी बनावट के साथ मीठी और मसालेदार लगती है।",
"10","71 ग्राम",
["2 मध्यम अंडे, फेंटे हुए","75 मिलीलीटर रेपसीड तेल + 2 पाउंड की लोफ़ टिन को चिकना करने के लिए 2 छोटे चम्मच","1 छोटा चम्मच वनीला एसेंस","3 बड़े चम्मच दानेदार स्वीटनर","300 ग्राम तोरी, कद्दूकस की हुई","200 ग्राम साबुत गेहूँ का आटा","1 छोटा चम्मच बेकिंग पाउडर","2 छोटे चम्मच पिसी दालचीनी"],
["ओवन को 180°/गैस 4 पर पहले से गरम करें।","लोफ़ टिन को चिकना करें और एक तरफ़ रख दें।","एक कटोरे में अंडे, तेल, वनीला एसेंस और स्वीटनर डालें, फिर अच्छी तरह फेंटें।","तोरी मिलाएँ, फिर आटा, बेकिंग पाउडर और दालचीनी मिलाएँ।","बेकिंग टिन में डालें और 30-35 मिनट तक बेक करें, जब तक छूने पर ठोस न लगे।"],
["यह जाँचने के लिए कि केक पका है या नहीं, बीच में एक छोटा, तेज़ चाकू डालें; यदि वह साफ़ निकलता है तो केक पक गया है। यदि चाकू पर कच्चा मिश्रण चिपका है तो इसे थोड़ा और समय चाहिए।","अलग रंग के केक के लिए पीली तोरी इस्तेमाल करके देखें।","ज़्यादा मसालेदार संस्करण के लिए, दालचीनी के साथ 2 छोटे चम्मच मिक्स्ड स्पाइस डालें।","फ्रीज़ करने के निर्देश: स्लाइस करें, फिर फ्रीज़ करने के लिए फ़ॉइल में लपेट दें (फिर ज़रूरत के अनुसार स्लाइस इस्तेमाल कर सकते हैं)।",fv(0)]))
r.append(R(7416466,"मसालेदार सब्ज़ी समोसे",
"यह कमाल की बात है कि आप शुरू से पेस्ट्री बनाए बिना या तले बिना भी कुरकुरे, स्वादिष्ट समोसे बना सकते हैं।",
"6","259 ग्राम",
["6 मिनी साबुत गेहूँ के टॉर्टिला रैप (लगभग 30 ग्राम प्रत्येक), आधे कटे हुए","स्प्रे तेल","2 छोटे चम्मच जीरा","2 प्याज़, बारीक कटे हुए","2 फांक लहसुन, कुचला हुआ","1 बड़ा चम्मच ताज़ा अदरक, कद्दूकस किया हुआ","1 बड़ा शकरकंद (लगभग 300 ग्राम), छोटे टुकड़ों में कटा हुआ","750 ग्राम फ्रोज़न मिली-जुली सब्ज़ियाँ","एक-एक चुटकी गरम मसाला, हल्दी और तिल","एक चुटकी मिर्च के गुच्छे (चिली फ्लेक्स)","थोड़ा-सा नींबू का रस निचोड़ा हुआ","1 बड़ा चम्मच ताज़ा धनिया, कटा हुआ","मैदा और पानी, गोंद जैसा पेस्ट बनने तक मिलाया हुआ"],
["रैप को आधा-आधा काटें ताकि वे सेहतमंद समोसे के लिए जेब (पॉकेट) बनाने को तैयार हों।","मध्यम आँच पर पैन में तेल के दो-तीन पंप स्प्रे करें और जीरा भूनें।","प्याज़, लहसुन और अदरक डालें और नरम होने तक भूनें।","चौकोर कटे शकरकंद (मटर के आकार के) और मिली-जुली सब्ज़ियाँ डालें। गरम मसाला, हल्दी, तिल और मिर्च के गुच्छे डालकर स्वाद बढ़ाएँ। ढक दें और मध्यम आँच पर लगभग 20 मिनट पकाएँ, या जब तक नरम न हो जाए (थोड़ा पानी छिड़कें ताकि मिश्रण सूखे नहीं और सब्ज़ियाँ नरम होने में मदद मिले)।","नींबू का रस डालें, ऊपर से ताज़ा धनिया छिड़कें और मिश्रण को ठंडा होने दें।","अपने रैप की \"जेबों\" के सीधे कटे हुए किनारे को बंद करने के लिए मैदे और पानी के पेस्ट का इस्तेमाल करें। यह गोंद जैसी गाढ़ापन वाला होना चाहिए।","ठंडे सब्ज़ी के मिश्रण से भरें और जेब का गोल किनारा बंद कर दें।","जेबों को चिपकने देने के लिए 30 मिनट फ्रिज में रखें।","सुनहरा होने तक ओवन में बेक करें।"],
["यह रेसिपी बैलेंस पत्रिका की कवर स्टार शिवाली ने मधुमेह (डायबिटीज़) से राहत की अपनी यात्रा के हिस्से के रूप में बनाई है।","इन समोसों को एयर फ्रायर में भी कुरकुरा और सुनहरा होने तक पकाया जा सकता है।",fv(2)]))
r.append(R(7419051,"मैकरल साल्सा रैप",
"मैक्सिकन अंदाज़ वाले इस व्यंजन से अपना ओमेगा-3 बढ़ाएँ, जो बारबेक्यू के लिए या पिकनिक में ठंडा खाने के लिए एकदम सही है।",
"4","287 ग्राम",
["1 छोटा लाल प्याज़, बारीक कटा हुआ","आधे नींबू (लाइम) का रस","1 बड़ा चम्मच एक्स्ट्रा-वर्जिन ऑलिव ऑयल","1/2 छोटा चम्मच जीरा (समतल भरा हुआ)","एक चुटकी मिर्च पाउडर","3-4 आलूबुखारे, गुठली निकालकर कटे हुए","8-10 ताज़े पके चेरी टमाटर, कटे हुए","1 बड़ा चम्मच कटा हुआ ताज़ा धनिया","4 मैकरल फ़िलेट (प्रत्येक 90 ग्राम)","4 रोटियाँ या साबुत गेहूँ के टॉर्टिला","100 ग्राम मिली-जुली सलाद की पत्तियाँ"],
["प्याज़, नींबू का रस, ऑलिव ऑयल, जीरा और मिर्च पाउडर को कटोरे में डालें और अच्छी तरह मिलाएँ।","आलूबुखारे, टमाटर और धनिया मिलाएँ। ढककर 5 मिनट के लिए एक तरफ़ रख दें।","इसी बीच, हर मैकरल फ़िलेट की त्वचा पर तीन चीरे लगाएँ।","हर मैकरल फ़िलेट को ग्रिल के नीचे त्वचा वाली तरफ़ ऊपर करके, या बारबेक्यू पर त्वचा वाली तरफ़ नीचे करके, लगभग 4 मिनट तक ग्रिल करें। यह फ़िलेट को पूरी तरह पकाने के लिए काफ़ी होना चाहिए, लेकिन न हो तो इसे पलटकर माँस वाली तरफ़ 1 मिनट और पकाएँ।","टॉर्टिला को गरम करने के बाद, उसमें कुछ सलाद की पत्तियाँ और एक मैकरल फ़िलेट रखें। ऊपर से एक मिठाई चम्मच साल्सा डालें और लपेट दें।","बचा हुआ साल्सा साथ में परोसें।"],
["साल्सा ग्रिल की हुई टूना, सैल्मन या झींगे या पोर्क स्टेक के साथ अच्छा लगता है।","मैकरल ओमेगा-3 के साथ-साथ विटामिन डी का भी बढ़िया स्रोत है।","यदि पिकनिक पर ले जा रहे हों, तो रैप को ग्रीसप्रूफ़ पेपर से ढकें और हर सिरे को मरोड़ दें।",fv(1)]))
r.append(R(7419400,"स्क्विड और झींगे की सींखें",
"प्रभावशाली, फिर भी सरल, ये मसालेदार सीफ़ूड सींखें पार्टी के लिए एक बढ़िया सेहतमंद नाश्ता हैं। पकने के बाद इन्हें गरम या ठंडा खाया जा सकता है।",
"10","35 ग्राम",
["300 ग्राम कच्चे स्क्विड के छल्ले","165 ग्राम कच्चे छिले हुए जंबो किंग झींगे","1 फांक लहसुन, कुचला हुआ","1 छोटी लाल मिर्च, बारीक कटी हुई","1 नींबू का रस और बारीक कद्दूकस किया हुआ छिलका","1 छोटा चम्मच रेपसीड तेल"],
["स्क्विड और झींगों को लहसुन, मिर्च, नींबू के रस और छिलके के साथ मिलाएँ, सजाने के लिए थोड़ा छिलका बचाकर रखें। 5 मिनट मैरीनेट होने के लिए छोड़ दें।","हर सींख में एक स्क्विड का छल्ला, एक झींगा और एक और स्क्विड का छल्ला पिरोएँ।","एक बड़े नॉन-स्टिक फ्राइंग पैन में तेल गरम करें और सींखों को एक बार पलटते हुए पकाएँ, ताकि झींगे पूरी तरह पक जाएँ और उनका माँस अपारदर्शी और गुलाबी या सफ़ेद हो जाए।"],
["यदि लकड़ी की सींखें इस्तेमाल कर रहे हैं, तो सीफ़ूड पिरोने से पहले उन्हें 10 मिनट पानी में भिगो दें।","सींखों को गरम ग्रिल के नीचे 4-5 मिनट तक, एक बार पलटते हुए भी पकाया जा सकता है, ताकि झींगा पूरी तरह पक जाए और रंग में अपारदर्शी हो जाए। ग्रिल के नीचे जलने से बचाने के लिए सींखों पर खुली लकड़ी पर थोड़ा फ़ॉइल लगा दें।",fv(0)]))
save(2,r)
